// ePayco Smart Checkout bootstrap.
// Opens the provider checkout when the page carries a pending session id
// generated by the backend (see PaymentEngine::Providers::Epayco).
(function () {
  document.addEventListener("DOMContentLoaded", function () {
    var root = document.querySelector("[data-epayco-session-id]");
    if (!root || typeof ePayco === "undefined") return;

    var sessionId = root.dataset.epaycoSessionId;
    if (!sessionId) return;

    var checkout = ePayco.checkout.configure({
      sessionId: sessionId,
      type: root.dataset.epaycoType || "standard",
      test: root.dataset.epaycoTest === "true"
    });

    if (typeof checkout.setHooks === "function") {
      checkout.setHooks({
        onClosed: function () {
          document.dispatchEvent(new CustomEvent("epayco:checkout:closed"));
        },
        onResponse: function () {
          document.dispatchEvent(new CustomEvent("epayco:checkout:response"));
        }
      });
    }

    checkout.open();
  });
})();